-- runtimepath を直接書き換える読み込み。
-- `:packadd!` は呼ぶたびに 'packpath' 全体を glob し、runtimepath の各エントリを realpath
-- 解決するため1回 0.5ms 前後かかる。rsplug はパッケージの場所を知っているので直接足す。
-- plugin/ や ftdetect/ の source が要る load は packadd 実装に任せる。
local here = string.match(debug.getinfo(1, 'S').source, '^@?(.*)/[^/]+$')
local packadd = assert(loadfile(here .. '/packadd.lua'))()

-- このファイルは <root>/pack/<name>/opt/<control-id>/lua/_rsplug/loader/rtp.lua に置かれる。
local opt_root = string.match(here, '^(.*)/[^/]+/lua/_rsplug/loader$')
local pack_root = opt_root and string.match(opt_root, '^(.*)/pack/[^/]+/opt$')

local M = {}

---`:packadd! id` と同じ位置に runtimepath を足す。
---packpath ルート配下の最初のエントリの直後、無ければ最初の after ディレクトリの直前に入れ、
---after/ があれば最初の after ディレクトリの直前に入れる。
---@param id string
function M.add(id)
	local rtp = vim.o.runtimepath
	-- エスケープされた区切りを含む runtimepath は分割できないので :packadd! に任せる。
	if not pack_root or rtp:find('\\', 1, true) then
		packadd.add(id)
		return
	end
	local dir = opt_root .. '/' .. id
	local entries = vim.split(rtp, ',', { plain = true })
	local insp, after_insp
	for i, entry in ipairs(entries) do
		if entry == dir then
			return
		end
		if not insp and entry:sub(1, #pack_root + 1) == pack_root .. '/' then
			insp = i + 1
		end
		if not after_insp and entry:match('/after/?$') then
			after_insp = i
		end
	end
	insp = insp or after_insp or (#entries + 1)
	table.insert(entries, insp, dir)
	local after = dir .. '/after'
	if vim.uv.fs_stat(after) then
		-- dir を挿入したので、それより後ろにある after の位置は1つずれる。
		local pos = after_insp and (after_insp >= insp and after_insp + 1 or after_insp) or (#entries + 1)
		table.insert(entries, pos, after)
	end
	vim.o.runtimepath = table.concat(entries, ',')
end

M.load = packadd.load

return M
